/**
 * Settings -> Abilities & commands: the directory of every feature.
 *
 * Owner requirement (2026-10-22, Gemini Q2/Q8): Settings must include a
 * directory/search that indexes every feature with exactly five plain labels;
 * rows that are not switches must say so honestly, with an example phrase and
 * a screen path; never a fake switch.
 *
 * THE DATA IS NOT HAND-TYPED. `src/feature-directory.js` is generated by
 * `tools/gen_feature_directory.py` from the canonical, checked
 * `contract/feature-controls.json`; this suite checks the page against that
 * contract and fails if the generated copy is stale (source sha), if a feature
 * is missing, if a sixth label appears, or if a row lost its example/screen
 * path. It also proves the card is an INDEX: no button, toggle, checkbox or
 * select inside the list, and the only interactive thing is the filter.
 */
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as K from "./uikit.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const read = (p) => readFileSync(join(HERE, "..", p));
const readJSON = (p) => JSON.parse(read(p).toString("utf8"));
const FIXTURE = readJSON("tests/fixtures/feature-directory.json");
const CONTRACT = readJSON("../contract/feature-controls.json");
// The five labels come from the contract itself: this suite checks that the
// page's copy carries exactly the contract's five, in the contract's order, and
// that the generated file's label_order is the same list (so the page cannot
// stamp its own wording on them).
const LABELS = Object.keys(CONTRACT.labels);

const { base, close } = await K.serve();
const browser = await K.launch();
const fails = [];
const check = async (name, fn) => {
  try {
    await fn();
    console.log(`ok    ${name}`);
  } catch (e) {
    fails.push(name);
    console.log(`FAIL  ${name}\n      ${e.message}`);
  }
};

const open = async () => {
  const page = await K.open(browser, base, "settings.html", {},
    { width: 1000, height: 2000 });
  await page.waitForFunction(
    () => document.querySelectorAll("#fd-list .fd-row").length > 0,
    { timeout: 10000 });
  return page;
};

const directory = (page) => page.evaluate(() => {
  const card = document.getElementById("fd-title")?.closest(".card");
  const rows = [...document.querySelectorAll("#fd-list .fd-row")];
  return {
    cardId: card ? (card.id || "(anonymous)") : null,
    count: rows.length,
    labels: [...new Set(rows.map((r) =>
      (r.querySelector(".fd-label") || {}).textContent || ""))].sort(),
    names: rows.map((r) => (r.querySelector(".fd-name") || {}).textContent || ""),
    missingExample: rows.filter((r) => !(r.querySelector(".fd-example") || {})
      .textContent).length,
    missingWhere: rows.filter((r) => !(r.querySelector(".fd-where") || {})
      .textContent).length,
    controls: document.querySelectorAll(
      "#fd-list button, #fd-list input, #fd-list select, #fd-list textarea, " +
      "#fd-list [role=switch], #fd-list [role=checkbox]").length,
    disclosures: document.querySelectorAll("#fd-list details").length,
  };
});

const countsOf = (rows) => {
  const counts = {};
  for (const row of rows) counts[row.label] = (counts[row.label] || 0) + 1;
  return counts;
};

await check("the generated copy matches the canonical contract", async () => {
  // A changed contract must force a regeneration: the page's copy carries the
  // contract's sha256, so this fails instead of quietly showing old labels.
  const sha = createHash("sha256").update(read("../contract/feature-controls.json"))
    .digest("hex");
  assert.equal(FIXTURE.source_sha256, sha,
    "feature-directory.js/fixture is stale - run python -B tools/gen_feature_directory.py");
  assert.equal(FIXTURE.feature_count, CONTRACT.feature_count);
  // The declared counts must match the rows each file actually carries, so a
  // new feature row needs no number typed here.
  assert.equal(FIXTURE.feature_count, FIXTURE.rows.length,
    `the fixture says ${FIXTURE.feature_count} features but carries ${FIXTURE.rows.length} rows`);
  assert.equal(CONTRACT.feature_count, CONTRACT.features.length,
    `the contract says ${CONTRACT.feature_count} features but carries ${CONTRACT.features.length} rows`);
  assert.equal(LABELS.length, 5, `the contract has ${LABELS.length} labels`);
  assert.deepEqual(FIXTURE.label_order, LABELS,
    "the generated order is not the contract's label order");
  assert.deepEqual(Object.keys(FIXTURE.labels), LABELS);
  // The page imports the GENERATED module, not the fixture: prove its embedded
  // source_sha256 is the same one, so a fixture regenerated without the module
  // (or the other way round) fails instead of showing labels the contract no
  // longer has.
  const moduleText = read("src/feature-directory.js").toString("utf8");
  const moduleSha = (moduleText.match(/"source_sha256": "([0-9a-f]{64})"/) || [])[1];
  assert.equal(moduleSha, sha,
    "src/feature-directory.js is stale - run python -B tools/gen_feature_directory.py");
  assert.equal(moduleSha, FIXTURE.source_sha256);
  // Wire the generator's own --check into a required battery: this suite runs
  // in the frontend job, so a hand-edited generated file or a stale copy fails
  // CI even if nobody runs the generator by hand. Both interpreter names are
  // tried (Windows uses `python`, CI's ubuntu uses `python3`).
  const root = join(HERE, "..", "..");
  let out = null;
  let last = null;
  for (const engine of ["python3", "python"]) {
    try {
      out = execFileSync(engine,
        ["-B", "tools/gen_feature_directory.py", "--check"],
        { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
      break;
    } catch (e) {
      last = e;
    }
  }
  assert.ok(out !== null,
    `tools/gen_feature_directory.py --check did not run: ${last && (last.stderr || last.message)}`);
  assert.match(out, /match the feature contract/);
});

await check(`the page renders all ${CONTRACT.features.length} features, grouped under exactly five labels`, async () => {
  const page = await open();
  const d = await directory(page);
  assert.equal(d.count, CONTRACT.features.length, `the page shows ${d.count} rows`);
  assert.deepEqual(d.labels, [...LABELS].sort());
  assert.equal(d.missingExample, 0, "a row lost its example phrase");
  assert.equal(d.missingWhere, 0, "a row lost its screen path");
  // The counts come from the contract, never from the page's own wording.
  const expected = countsOf(CONTRACT.features);
  const shown = countsOf(FIXTURE.rows);
  assert.deepEqual(shown, expected,
    `label counts drifted: page ${JSON.stringify(shown)} contract ${JSON.stringify(expected)}`);
  assert.deepEqual([...new Set(FIXTURE.rows.map((r) => r.title))].sort(),
    [...new Set(CONTRACT.features.map((f) => f.name))].sort());
  await page.close();
});

await check("it is a directory, not a second settings surface", async () => {
  const page = await open();
  const d = await directory(page);
  assert.equal(d.controls, 0,
    `${d.controls} control(s) were drawn inside the directory - it must be words only`);
  // Two kinds of interactive element, and neither changes a setting: the
  // filter box (hides rows locally) and the five native <details> disclosures
  // the labels are grouped under. No button/toggle/checkbox/select anywhere.
  const filter = await page.evaluate(() => {
    const el = document.getElementById("fd-filter");
    return el ? { type: el.type, tag: el.tagName } : null;
  });
  assert.deepEqual(filter, { type: "search", tag: "INPUT" });
  assert.equal(d.disclosures, 5,
    `${d.disclosures} disclosure groups - expected the five labels`);
  await page.close();
});

await check("the filter narrows the list and clearing it restores every row", async () => {
  const page = await open();
  await page.locator("#fd-filter").fill("clipboard");
  await page.waitForTimeout(250);
  const shown = await directory(page);
  assert.ok(shown.count > 0 && shown.count < CONTRACT.features.length,
    `the filter showed ${shown.count} rows for "clipboard"`);
  const countText = await page.locator("#fd-count").textContent();
  assert.match(countText, new RegExp(`${shown.count} of ${CONTRACT.features.length}`), countText);
  await page.locator("#fd-filter").fill("");
  await page.waitForTimeout(250);
  assert.equal((await directory(page)).count, CONTRACT.features.length);
  await page.close();
});

await check("both live screen names are real: the directory ships on both apps", async () => {
  // R1: #748 shipped the desktop directory and #749 ships the phone one, so the
  // contract's "(planned)" marker must reach NEITHER half any more. A re-added
  // marker names a screen that exists; check_feature_controls.py refuses it on
  // the contract side, and this holds the generated page copy to the same rule.
  const plannedDesktop = FIXTURE.rows.filter((r) => /\(planned\)/.test(r.where_desktop));
  const plannedPhone = FIXTURE.rows.filter((r) => /\(planned\)/.test(r.where_phone));
  assert.deepEqual(plannedDesktop.map((r) => r.id), [],
    "a live desktop screen path still says (planned)");
  assert.deepEqual(plannedPhone.map((r) => r.id), [],
    "the phone directory ships now (#749), so no phone path may say (planned)");
  assert.ok(FIXTURE.rows.filter((r) => r.where_phone === "All features and abilities").length > 100,
    "the phone half of the directory rows is not the live directory name");
  const page = await open();
  const title = await page.evaluate(
    () => (document.getElementById("fd-title") || {}).textContent || "");
  assert.equal(title.trim(), "All features and abilities",
    "the visible card title is not the live contract screen name");
  const text = await page.evaluate(() =>
    (document.getElementById("fd-title")?.closest(".card") || {}).innerText || "");
  // Users also know it as "Abilities & commands"; the card says both.
  assert.match(text, /Abilities & commands/);
  await page.close();
});

await check("the main search brings the directory card up; the card's box narrows rows", async () => {
  // R2: Settings search filters CARDS. A feature name brings this whole card up;
  // it does NOT reveal the one matching row inside it. The per-feature search is
  // the card's own box, which narrows the rows locally. Both sentences are in
  // the card's words so the page does not over-claim either behaviour.
  const page = await open();
  const type = async (text) => {
    await page.locator("#settings-search-input").fill(text);
    await page.waitForTimeout(250);
  };
  const cardShown = () => page.evaluate(() => {
    const card = document.getElementById("fd-title")?.closest(".card");
    return Boolean(card) && !card.hidden;
  });
  const intro = await page.evaluate(() =>
    (document.getElementById("fd-title")?.closest(".card") || {}).innerText || "");
  assert.match(intro, /main Settings search brings this whole card up/i,
    "the card does not say the main search shows the card, not a row");
  for (const words of ["clipboard history", "retirement what-if",
    "morning briefing"]) {
    await type(words);
    assert.equal(await cardShown(), true,
      `"${words}" did not find the abilities directory card`);
    await type("");
  }
  // The card's own filter is what finds a row.
  await page.locator("#fd-filter").fill("retirement");
  await page.waitForTimeout(250);
  const shown = await page.evaluate(() =>
    document.querySelectorAll("#fd-list .fd-row").length);
  assert.ok(shown > 0 && shown < CONTRACT.features.length, `the row filter showed ${shown} rows`);
  await page.close();
});

await check("a known multi-field row keeps its planned note", async () => {
  // R5: the honest note is words, not just a flag. Pin one row the contract
  // marks multi-field and prove the page renders the exact sentence.
  const note = "Settings control today; typed path still being wired.";
  const row = FIXTURE.rows.find((r) => r.id === "read-aloud");
  assert.ok(row, "the pinned multi-field row read-aloud is missing");
  assert.equal(row.note, note);
  const page = await open();
  const shown = await page.evaluate(() =>
    (document.querySelector('#fd-list [data-fd-id="read-aloud"] .fd-note') || {})
      .textContent || "");
  assert.equal(shown, note, "the page lost the multi-field planned note");
  await page.close();
});

await check("the labels are the owner's five, never a sixth", async () => {
  for (const label of LABELS) {
    assert.equal(typeof FIXTURE.labels[label], "string",
      `${label} has no plain description`);
    assert.ok(FIXTURE.labels[label].trim().length > 0);
  }
  const bad = FIXTURE.rows.filter((r) => !LABELS.includes(r.label));
  assert.deepEqual(bad.map((r) => r.id), []);
  // Every row keeps the honest "not a control" reminder the page renders by
  // words only; a future edit that treats status as a toggle fails here.
  assert.ok(FIXTURE.rows.every((r) => r.not_a_control === true));
});

await browser.close();
close();
console.log(fails.length ? `\n${fails.length} failed: ${fails.join(", ")}`
  : `\nthe abilities directory indexes all ${CONTRACT.features.length} features honestly`);
process.exit(fails.length ? 1 : 0);
